def build_graph():
    arcs=[('rise','龙谷与圣箱','rise'),('dragon-war','异魔侵攻与龙域军损','dragon-war'),('settlement','朝堂结算','settlement'),('godrealm','碎寂神界与条件力量','godrealm'),('upgrade','七星墓与国器','upgrade'),('third-war','第三国战统一七主','third-war'),('real','现实取证、订婚与军务','real'),('north','救佩、交职与北境均衡','north'),('revolt','义盟民心与主动追击','revolt'),('ghost','鬼城惨败与保军撤回','ghost'),('ending','交班与有限重生','ending')]
    nodes=[dict(id='zl-v06',kind='volume',parent_id=None,title='卷六：统一、退隐与生还',claim_kind='synthesis',summary='本卷全读，覆盖不等独读全书。',evidence=ev([1180,1386],'synthesis'))]
    for i,(key,title,_) in enumerate(arcs):nodes.append(dict(id='zl-v06-arc-'+key,kind='arc',parent_id='zl-v06',title=title,claim_kind='synthesis',narrative_order=i,evidence=[]))
    for key,card,characters,know in SCENES:
        content=card['content'];node=dict(id='zl-v06-'+key,kind='scene',parent_id='zl-v06-arc-'+content['arc'],title=card['title'],summary=content['summary'],claim_kind='fact',narrative_order=content['narrative_order'],asset_origin_key=card['origin_key'],character_origin_keys=[P+'character/'+x for x in characters],evidence=card['evidence'])
        if know:node['knowledge']=[dict(observer='reader' if who=='reader' else P+'character/'+who,state=state,**({'belief':what} if state=='misbelieves' else {'knowledge':what})) for who,state,what in know]
        nodes.append(node)
    E=[]
    def edge(a,b,kind,label,ns):
        eid='zl-v06-e-'+a+'-'+b;E.append(dict(id=eid,**{'from':'zl-v06-'+a,'to':'zl-v06-'+b},kind=kind,label=label,claim_kind='synthesis',evidence=ev(ns,'synthesis')));return eid
